/**
 * Image Generation API Route
 * POST /api/generate-image
 *
 * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
 *
 * Features:
 * - Server-side rate limiting (10 requests per minute per IP)
 * - Request validation
 * - Error handling with appropriate HTTP status codes
 * - Logging for debugging
 */

import { NextRequest, NextResponse } from 'next/server';
import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
import type { ImageGenerationRequest } from '@/lib/types/image-types';

/**
 * Rate limiting configuration
 * Tracks request counts per IP address
 */
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
const RATE_LIMIT_MAX_REQUESTS = 10;

/**
 * Checks if request is rate limited
 *
 * @param ip - Client IP address
 * @returns true if rate limited, false if allowed
 */
function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(ip);

  // No record or window expired - create new record
  if (!record || now > record.resetTime) {
    rateLimitMap.set(ip, {
      count: 1,
      resetTime: now + RATE_LIMIT_WINDOW,
    });
    return false;
  }

  // Increment count
  record.count++;

  // Check if over limit
  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    return true;
  }

  return false;
}

/**
 * Gets client IP address from request
 *
 * @param request - Next.js request object
 * @returns IP address string
 */
function getClientIP(request: NextRequest): string {
  // Try various headers that might contain the real IP
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }

  const realIP = request.headers.get('x-real-ip');
  if (realIP) {
    return realIP;
  }

  // Fallback to a default value
  return 'unknown';
}

/**
 * POST handler for image generation
 *
 * Request body:
 * {
 *   description: string,
 *   style?: {
 *     photographyStyle?: string,
 *     composition?: string,
 *     lighting?: string,
 *     aestheticContext?: string
 *   }
 * }
 *
 * Response:
 * {
 *   success: boolean,
 *   imageUrl?: string,
 *   imageBase64?: string,
 *   error?: string,
 *   message?: string
 * }
 */
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    // Get client IP for rate limiting
    const clientIP = getClientIP(request);

    console.log('[API] Image generation request received from IP:', clientIP);

    // Check rate limiting
    if (isRateLimited(clientIP)) {
      console.warn('[API] Rate limit exceeded for IP:', clientIP);
      return NextResponse.json(
        {
          success: false,
          error: 'RATE_LIMITED',
          message: 'Too many requests. Please wait a minute before trying again.',
        },
        {
          status: 429,
          headers: {
            'Retry-After': '60',
          },
        }
      );
    }

    // Check if OPENROUTER_API_KEY is configured
    const apiKey = process.env.OPENROUTER_API_KEY;
    if (!apiKey) {
      console.error('[API] OPENROUTER_API_KEY not configured');
      return NextResponse.json(
        {
          success: false,
          error: 'SERVICE_UNAVAILABLE',
          message: 'Image generation service is not configured. Please contact support.',
        },
        { status: 503 }
      );
    }

    // Parse request body
    let body: ImageGenerationRequest;
    try {
      body = await request.json();
    } catch (error) {
      console.error('[API] Invalid JSON in request body:', error);
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_REQUEST',
          message: 'Invalid request format',
        },
        { status: 400 }
      );
    }

    // Validate request body
    const { description, style } = body;

    if (!description || typeof description !== 'string' || description.trim() === '') {
      console.error('[API] Missing or invalid description');
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_DESCRIPTION',
          message: 'Outfit description is required',
        },
        { status: 400 }
      );
    }

    // Validate description length
    if (description.length > 1000) {
      console.error('[API] Description too long:', description.length);
      return NextResponse.json(
        {
          success: false,
          error: 'DESCRIPTION_TOO_LONG',
          message: 'Outfit description is too long. Please keep it under 1000 characters.',
        },
        { status: 400 }
      );
    }

    console.log('[API] Generating image for description:', {
      descriptionLength: description.length,
      style: style || 'default',
    });

    // Create image client and generate image
    const imageClient = new OpenRouterImageClient(apiKey);

    const result = await imageClient.generateOutfitImage(description, style);

    const duration = Date.now() - startTime;
    console.log('[API] Image generation completed in', duration, 'ms', {
      success: result.success,
      error: result.error || 'none',
    });

    // Return response with appropriate status code
    if (result.success) {
      return NextResponse.json(result, {
        status: 200,
        headers: {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
        },
      });
    } else {
      // Determine status code based on error type
      let statusCode = 500;
      if (result.error === 'RATE_LIMITED') {
        statusCode = 429;
      } else if (result.error === 'INVALID_DESCRIPTION') {
        statusCode = 400;
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        statusCode = 503;
      }

      return NextResponse.json(result, {
        status: statusCode,
      });
    }
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error('[API] Unexpected error during image generation:', error);
    console.error('[API] Error occurred after', duration, 'ms');

    return NextResponse.json(
      {
        success: false,
        error: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred. Please try again later.',
      },
      { status: 500 }
    );
  }
}

/**
 * GET handler - not supported
 * Returns 405 Method Not Allowed
 */
export async function GET() {
  return NextResponse.json(
    {
      success: false,
      error: 'METHOD_NOT_ALLOWED',
      message: 'GET method is not supported. Use POST to generate images.',
    },
    { status: 405 }
  );
}

/**
 * OPTIONS handler for CORS preflight
 */
export async function OPTIONS() {
  return NextResponse.json(
    {},
    {
      status: 200,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      },
    }
  );
}

/**
 * LooksInspiration Component
 * Displays generated outfit images in chat interface (Customer Journey Step 4)
 *
 * Features:
 * - Loading state with skeleton animation
 * - Error state with retry functionality
 * - Success state with image display
 * - Click to expand/zoom with dialog
 * - Download functionality
 * - Mobile-responsive design
 * - WCAG 2.1 AA accessibility
 */

'use client';

import { useState } from 'react';
import Image from 'next/image';
import { Download, RefreshCw, ZoomIn, AlertCircle, Loader2 } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Skeleton } from '@/components/ui/skeleton';
import type { LooksInspirationProps } from '@/lib/types/image-types';

export function LooksInspiration({
  outfitDescription,
  imageUrl,
  imageBase64,
  isLoading = false,
  error,
  onRetry,
  onGenerateAnother,
  onDownload,
}: LooksInspirationProps) {
  const [isZoomOpen, setIsZoomOpen] = useState(false);
  const [imageError, setImageError] = useState(false);

  // Determine image source (prefer URL over base64)
  const imageSrc = imageUrl || imageBase64;

  /**
   * Handles image download
   */
  const handleDownload = () => {
    if (onDownload) {
      onDownload();
      return;
    }

    // Default download implementation
    if (!imageSrc) return;

    try {
      // Create download link
      const link = document.createElement('a');
      link.href = imageSrc;
      link.download = `ootday-outfit-${Date.now()}.png`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (err) {
      console.error('[LooksInspiration] Download failed:', err);
    }
  };

  /**
   * Renders loading state
   */
  if (isLoading) {
    return (
      <Card className="max-w-md mx-auto my-4" role="status" aria-live="polite">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-sm text-gray-600">
              <Loader2 className="w-4 h-4 animate-spin" aria-hidden="true" />
              <span>กำลังสร้างภาพชุดของคุณ...</span>
            </div>
            <Skeleton className="w-full h-64 rounded-lg" />
            <div className="space-y-2">
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders error state
   */
  if (error || !imageSrc) {
    return (
      <Card className="max-w-md mx-auto my-4 border-red-200 bg-red-50" role="alert" aria-live="assertive">
        <CardContent className="p-4">
          <div className="space-y-3">
            <div className="flex items-center gap-2 text-red-600">
              <AlertCircle className="w-5 h-5 flex-shrink-0" aria-hidden="true" />
              <div>
                <p className="font-medium text-sm">ไม่สามารถสร้างภาพได้</p>
                <p className="text-xs text-red-500 mt-1">
                  {error || 'เกิดข้อผิดพลาดในการสร้างภาพ กรุณาลองใหม่อีกครั้ง'}
                </p>
              </div>
            </div>

            {onRetry && (
              <Button
                onClick={onRetry}
                variant="outline"
                size="sm"
                className="w-full border-red-300 hover:bg-red-100"
                aria-label="Retry image generation"
              >
                <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                ลองใหม่อีกครั้ง
              </Button>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  /**
   * Renders success state with image
   */
  return (
    <>
      <Card className="max-w-md mx-auto my-4 overflow-hidden">
        <CardContent className="p-0">
          {/* Image Display */}
          <div className="relative group">
            <div className="relative w-full aspect-[3/4] bg-gray-100">
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Outfit visualization: ${outfitDescription}`}
                  fill
                  className="object-cover"
                  sizes="(max-width: 768px) 100vw, 500px"
                  onError={() => setImageError(true)}
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-12 h-12" />
                </div>
              )}
            </div>

            {/* Zoom Button Overlay */}
            <button
              onClick={() => setIsZoomOpen(true)}
              className="absolute inset-0 bg-black/0 hover:bg-black/10 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100 focus:opacity-100 focus:outline-none focus:ring-2 focus:ring-primary focus:ring-inset"
              aria-label="Zoom image"
            >
              <div className="bg-white/90 rounded-full p-2">
                <ZoomIn className="w-6 h-6 text-gray-700" aria-hidden="true" />
              </div>
            </button>
          </div>

          {/* Image Caption and Actions */}
          <div className="p-4 space-y-3">
            {/* Caption */}
            <div>
              <p className="text-sm font-medium text-gray-900">Looks Inspiration 💫</p>
              <p className="text-xs text-gray-600 mt-1 line-clamp-2">{outfitDescription}</p>
            </div>

            {/* Action Buttons */}
            <div className="flex gap-2">
              {/* Download Button */}
              <Button
                onClick={handleDownload}
                variant="outline"
                size="sm"
                className="flex-1"
                aria-label="Download outfit image"
              >
                <Download className="w-4 h-4 mr-2" aria-hidden="true" />
                ดาวน์โหลด
              </Button>

              {/* Generate Another Button (Optional) */}
              {onGenerateAnother && (
                <Button
                  onClick={onGenerateAnother}
                  variant="outline"
                  size="sm"
                  className="flex-1"
                  aria-label="Generate another outfit variation"
                >
                  <RefreshCw className="w-4 h-4 mr-2" aria-hidden="true" />
                  สร้างอีกครั้ง
                </Button>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Zoom Dialog */}
      <Dialog open={isZoomOpen} onOpenChange={setIsZoomOpen}>
        <DialogContent className="max-w-4xl w-full max-h-[90vh] overflow-auto">
          <DialogHeader>
            <DialogTitle className="sr-only">
              Outfit image - {outfitDescription}
            </DialogTitle>
          </DialogHeader>

          <div className="relative w-full">
            <div className="relative w-full aspect-[3/4] max-h-[80vh] bg-gray-100 rounded-lg overflow-hidden">
              {!imageError ? (
                <Image
                  src={imageSrc}
                  alt={`Full size outfit visualization: ${outfitDescription}`}
                  fill
                  className="object-contain"
                  sizes="(max-width: 1024px) 100vw, 1024px"
                  priority
                />
              ) : (
                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                  <AlertCircle className="w-16 h-16" />
                </div>
              )}
            </div>

            {/* Caption in Dialog */}
            <div className="mt-4">
              <p className="text-sm font-medium text-gray-900">{outfitDescription}</p>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

